<?php
namespace App\Http\Controllers;
use App\Models\Order;use App\Models\ReturnRequest;use Illuminate\Http\JsonResponse;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Inertia\Inertia;use Inertia\Response;
class ReturnRequestController extends Controller{public function index():Response{return Inertia::render('admin/Returns',['requests'=>ReturnRequest::query()->with(['order:id,code,customer_name,total','customer:id,name,email','salesApprover:id,name','adminApprover:id,name','receiver:id,name'])->latest()->paginate(20)->through(fn(ReturnRequest$r)=>['id'=>$r->id,'status'=>$r->status,'reason'=>$r->reason,'customerNote'=>$r->customer_note,'refundAmount'=>(int)$r->refund_amount,'refundStatus'=>$r->refund_status,'order'=>$r->order?->only(['id','code','customer_name','total']),'customer'=>$r->customer?->only(['id','name','email']),'salesApprover'=>$r->salesApprover?->only(['id','name']),'adminApprover'=>$r->adminApprover?->only(['id','name']),'receiver'=>$r->receiver?->only(['id','name']),'createdAt'=>$r->created_at?->toIso8601String()])]);}public function salesApprove(Request$request,ReturnRequest$returnRequest):RedirectResponse{abort_unless(in_array($request->user()->role?->value,['admin','sales'],true),403,'Chỉ Bán hàng hoặc Admin được duyệt bước bán hàng.');abort_unless($returnRequest->status==='customer_requested',422,'Yêu cầu không ở bước Bán hàng.');$returnRequest->update(['status'=>'awaiting_admin','sales_approved_by'=>$request->user()->id,'sales_approved_at'=>now()]);return back()->with('success','Bán hàng đã tiếp nhận và chuyển yêu cầu trả hàng cho Admin.');}public function adminApprove(Request$request,ReturnRequest$returnRequest):RedirectResponse{abort_unless($request->user()->isAdmin(),403,'Chỉ Admin được phê duyệt yêu cầu trả hàng.');abort_unless($returnRequest->status==='awaiting_admin',422,'Yêu cầu chưa qua bước Bán hàng.');$returnRequest->update(['status'=>'awaiting_receive','admin_approved_by'=>$request->user()->id,'admin_approved_at'=>now(),'refund_amount'=>$returnRequest->order?->total??0]);return back()->with('success','Admin đã duyệt. Chờ hàng hoàn về kho để kiểm tra.');}public function receive(Request$request,ReturnRequest$returnRequest):RedirectResponse{abort_unless($request->user()->role?->value==='sales',403,'Chỉ tài khoản Bán hàng được kiểm tra hàng hoàn.');abort_unless($returnRequest->status==='awaiting_receive',422,'Yêu cầu chưa sẵn sàng để kiểm tra hàng.');$note=$request->string('inspection_note')->toString();abort_if($note==='',422,'Vui lòng ghi nhận kết quả kiểm tra hàng.');$returnRequest->update(['status'=>'inspected','received_by'=>$request->user()->id,'received_at'=>now(),'inspection_note'=>$note]);return back()->with('success','Bán hàng đã kiểm tra hàng. Có thể thực hiện hoàn tiền.');}public function refund(Request$request,ReturnRequest$returnRequest):RedirectResponse{abort_unless($request->user()->isAdmin(),403,'Chỉ Admin được xác nhận hoàn tiền.');abort_unless($returnRequest->status==='inspected',422,'Hàng chưa được kiểm tra đạt yêu cầu.');DB::transaction(function()use($returnRequest):void{$returnRequest->update(['status'=>'refunded','refund_status'=>'completed','refunded_at'=>now()]);$returnRequest->order?->update(['status'=>'Hoàn tiền']);});return back()->with('success','Đã xác nhận hoàn tiền và hoàn tất yêu cầu trả hàng.');}public function storeCustomer(Request$request,Order$order):JsonResponse{abort_unless($order->user_id===$request->user()->id,404);abort_unless($order->status==='Đã giao',422,'Chỉ đơn hàng đã giao mới có thể yêu cầu trả hàng.');abort_if(ReturnRequest::query()->where('order_id',$order->id)->whereNotIn('status',['refunded','rejected'])->exists(),422,'Đơn hàng đã có yêu cầu trả hàng.');$data=$request->validate(['reason'=>['required','string','max:500'],'customer_note'=>['nullable','string','max:2000']]);$return=ReturnRequest::create(['order_id'=>$order->id,'customer_id'=>$request->user()->id,'reason'=>$data['reason'],'customer_note'=>$data['customer_note']??null,'status'=>'customer_requested','refund_amount'=>$order->total]);$order->update(['status'=>'Yêu cầu trả hàng']);return response()->json(['request_id'=>$return->id,'order_id'=>$order->id,'status'=>$order->status]);}}
